    },
    "D5_scope_discipline": {
      "score": 10,
      "weight": 7,
      "rationale": "Started at 10. No deductions. The plan has an explicit 'What this plan does NOT include' section that correctly lists all 6 audit-ruled-out decisions. No scope creep or spirit-of-the-law violations are visible."
    },
    "D6_substrate_trust": {
      "score": 8,
      "weight": 14,
